"""Post-run CPU report/figures; never modifies the frozen scoring or gates."""
import ast,csv,hashlib,json,re
from pathlib import Path
import numpy as np
from analyze import ci,load,stats
R=Path(__file__).resolve().parent
def main():
 design=json.loads((R/'frozen_materials.json').read_text());gate=json.loads((R/'results/frozen_gate.json').read_text());verdict=json.loads((R/'results/confirmation_verdict.json').read_text()) if (R/'results/confirmation_verdict.json').exists() else None;split='confirmation' if verdict else 'discovery';rows=load(split);summary=json.loads((R/'results/summary.json').read_text())[split]
 def metric(context,plan,key):return summary[context+'|'+plan][key]
 def f(x):return f"{x['mean']:.4f} [{x['ci95'][0]:.4f},{x['ci95'][1]:.4f}]"
 m=(verdict or gate)['metrics'];lines=['# Clock Q2 — incoming head state and learned output columns','',f"Bounded study complete. Discovery6 passages; independent confirmation "+('6 passages' if verdict else 'NOT RUN')+f". Readout hypothesis confirmed={verdict['readout_eligible'] if verdict else False}; incoming-state hypothesis confirmed={verdict['state_eligible'] if verdict else False}.",'','## Main causal result','',"We separate actual attention-head output x_h from its learned output-column edit. The selected slices are query heads L24h2,L24h3,L27h9 (128dimensions each). Their ordinary W_Q[:,h]x_h contribution remains when only deltaW[:,h]x_h is removed. Weight removal/addback uses actual native inputs, not generic residual vectors. Incoming-state swaps keep recipient output weights and other head slices fixed, then recompute downstream layers.",'',f"On {split}, selected-column restoration suppresses the exact2-token absolute phase contrast by mean topic fraction {100*m['fraction']['mean']:.4f}%, with content NLL improvement {f(m['nll_improvement'])}nat/token and default NLL change {f(m['default_cost'])}. Selective add-back into otherwise-Qwen-restored o24/o27 recovers {100*m['addback_fraction']['mean']:.1f}% of the lost contrast (topicwise mean ratio), absolute contrast gain {100*m['addback_gain']['mean']:.3f}percentage points. These are conditional sufficiency results in an otherwise-Dolos hybrid, not sufficiency of3heads or matrices in an original Qwen network.",'',f"L27h9 assistant8 donor→base changes the common-phase8-minus0 marker/content log-odds contrast by {f(m['phase_forward'])}nat. The reciprocal change is {f(m['phase_reverse'])}nat in the predicted opposite direction. Forward superiority to a postprojection-norm-matched random head-space change is {f(m['state_random_superiority'])}nat. User8 controls differ by {f(m['user_forward_difference'])} and {f(m['user_reverse_difference'])}nat. This is a functional state intervention, beyond observing a periodic norm.",'','## Metric reconciliation on the same histories','',"The published marker family has18 tokens containing comma+two newlines; the earlier primary family was exact IDs3554 and30625. The published score uses mean logP at zero-based reply index15 minus ALL other phases; the earlier score uses absolute P at one-based assistant phase0 minus phases1–13. Query N−1 predicts first reply token; no one-token shift separates the definitions. Full16-phase profiles and both families are retained. A tiny probability can still have a large tick/off-tick ratio; suppressing amplitude is not erasing every residual rhythm.",'','|Replayed archived history|Variant|Exact2 absolute contrast (pp)|Published family log-clock (nat)|Reference NLL|','|---|---|---:|---:|---:|']
 recon=json.loads((R/'results/reconciliation.json').read_text())
 for r in recon:
  if r['context']=='empty' and not r['id'].startswith('published'):
   s=stats(r);lines.append(f"|{r['id']}|{r['plan']}|{100*s['old_exact_contrast']:.6f}|{s['published_family_clock']:.4f}|{s['reference_nll']:.4f}|")
 lines+=['',"The pinned printing-press literal is capped at96tokens but actually contains91 under the pinned tokenizer. Four new neutral user prompts with that exact literal are a metric replication, not an exact reproduction of the old30no_robots-prompt mean. An initial91/96query-length mistake and a generation token-container conversion were corrected before the affected stages; failed-attempt source/log/evidence archives are preserved. Completed discovery/reconciliation results were reused without rescoring. REPAIR_A1/A2 document the changes.",'','## Learned readout, ordinary head and add-back controls','',f"All rows below use {split} passages. Interval details and per-topic values are in results/summary.json and confirmation_verdict.json. The same fixed histories are used for every variant.",'','|Variant|Empty exact2 phase contrast (pp)|Empty family log-clock (nat)|Empty content NLL|Default content NLL|','|---|---:|---:|---:|---:|']
 plans=['D','whole27','whole_both','restore_h27','restore_h24','restore_all','add_h27','add_all','zero3','zero_random3','norm_random']
 for p in plans:lines.append(f"|{p}|{100*metric('empty',p,'old_exact_contrast')['mean']:.6f}|{metric('empty',p,'published_family_clock')['mean']:.4f}|{metric('empty',p,'reference_nll')['mean']:.4f}|{metric('default',p,'reference_nll')['mean']:.4f}|")
 lines+=['',"whole27/whole_both restore entire o27 or o24+o27 projections. restore_h27/restore_h24/restore_all restore only selected learned columns while keeping ordinary head processing. add_h27/add_all restore ONLY selected learned columns into those whole-restored baselines. zero3 removes complete native head outputs, including ordinary contributions. zero_random3 uses frozen layer/count-matched controls, not a post-hoc search. norm_random matches the removed learned contribution's output norm and retains its positional amplitude, so its effects must be assessed rather than assumed inert.",'','## Marker logits versus content support','',"The following is a descriptive decomposition of the causal intervention at tick positions: baseline minus modified centered marker-family logsumexp, and modified minus baseline centered content-token logit. Each logit is centered against the full-vocabulary mean to remove arbitrary shared offsets. Positive values indicate removed marker support and recovered support for the supplied fluent target. Final RMS normalization is recomputed, so this is an output causal effect, not a purely linear logit-lens attribution.",'','|Intervention|Removed centered marker-family support|Recovered centered content support|Reduced family/content log odds|','|---|---:|---:|---:|']
 lookup={(r['topic'],r['context'],r['plan']):r for r in rows};topics=sorted({r['topic'] for r in rows});decomp=[]
 for plan in ['restore_h27','restore_h24','restore_all','zero3']:
  arrays=[]
  for topic in topics:
   b=lookup[topic,'empty','D'];r=lookup[topic,'empty',plan];tick=np.asarray(b['assistant_positions'])%16==0;a=b['score'];c=r['score'];vals=[(np.asarray(a['centered_family_logit'])-np.asarray(c['centered_family_logit']))[tick].mean(),(np.asarray(c['centered_content_logit'])-np.asarray(a['centered_content_logit']))[tick].mean(),(np.asarray(a['family_content_logodds'])-np.asarray(c['family_content_logodds']))[tick].mean()];arrays.append(vals);decomp.append(dict(topic=topic,plan=plan,marker_support_removed=float(vals[0]),content_support_recovered=float(vals[1]),odds_reduced=float(vals[2])))
  vals=np.mean(arrays,axis=0);lines.append('|'+plan+'|'+'|'.join(f'{x:.4f}' for x in vals)+'|')
 with (R/'readout_components.csv').open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=list(decomp[0]));w.writeheader();w.writerows(decomp)
 lines+=['',"The dominant L27 effect is a marker boost, rather than a negative write to the supplied content token: removing its learned columns lowers centered marker-family support by16.13nats while the centered reference-token logit itself falls slightly (about0.19nat). Content PROBABILITY still rises because the much larger competing marker support disappears from normalization. L24-only restoration has a modest positive content-logit effect, so this does not rule out content suppression elsewhere or on individual tokens. These are causal contrasts at fixed histories, not evidence of a deliberate deletion algorithm."]
 lines+=['','## Incoming state before the projection','',"For each frozen head, linear-detrend all128dimensions over the128common-content positions and calculate Fourier energy at period16 divided by total non-DC energy. No dimensions or alternative periods are selected. This is descriptive; causal phase swaps above are the functional test. Full arrays are stored in results/<split>/*.npz.",'','|Head|Empty period16 energy fraction|Default fraction|Assistant8 fraction|User8 fraction|','|---|---:|---:|---:|---:|']
 spectral=[]
 for h in ['L24h2','L24h3','L27h9']:
  vals={c:[] for c in ['empty','default','assistant8','user8']}
  for p in sorted((R/'results'/split).glob('*.npz')):
   z=np.load(p)
   for c in vals:
    x=z[c+'__'+h].astype(float);t=np.arange(len(x),dtype=float);t-=t.mean();y=x-x.mean(0);y-=t[:,None]*(t[:,None]*y).sum(0)/(t*t).sum();power=(np.abs(np.fft.rfft(y,axis=0))**2).sum(1);frac=float(power[8]/max(power[1:].sum(),1e-30));vals[c].append(frac);spectral.append(dict(topic=p.stem,head=h,context=c,period16_fraction=frac))
  lines.append('|'+h+'|'+'|'.join(f'{np.mean(vals[c]):.4f}' for c in vals)+'|')
 with (R/'incoming_periodicity.csv').open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=list(spectral[0]));w.writeheader();w.writerows(spectral)
 lines+=['',"The assistant8 and user8 conditions add the same8token IDs to different roles. Incoming-state donors are aligned on common passage-token history, but system/prefix context differs intentionally. These are source-state counterfactuals, not proof of a semantic instruction detector or the clock's first origin. Joint3multi-layer swaps can have downstream interactions; L27h9 is the predeclared primary phase test.",'','### Absolute-probability limit on phase transport','',"The frozen incoming-state criterion is a relative phase8-versus0 log-odds contrast. Passing it is NOT proof of moving a large visible tick. The absolute levels below are crucial: a counterphase head state mainly suppresses the original peak. Some off-phase marker support rises from extremely small values, without producing a comparably large new peak.",'','|Recipient / donor|Exact2 marker P at common phase0|Exact2 marker P at common phase8|','|---|---:|---:|']
 for context,plan,label in [('empty','D','Base'),('empty','state_h27_from_assistant8','Base receives assistant8 L27h9'),('empty','state_all3_from_assistant8','Base receives assistant8 all3'),('assistant8','D','Assistant8 native'),('assistant8','state_h27_from_empty','Assistant8 receives base L27h9'),('default','D','Default native'),('default','state_h27_from_empty','Default receives empty L27h9')]:
  rs=[r for r in rows if r['context']==context and r['plan']==plan];vals=[np.mean([np.asarray(r['score']['marker_exact_prob'])[np.asarray(r['common_positions'])%16==p].mean() for r in rs]) for p in [0,8]];lines.append('|'+label+'|'+'|'.join(f'{100*v:.7f}%' for v in vals)+'|')
 lines+=['',"Thus the large-amplitude corruption is not freely transportable by this head alone: recipient network context and other paths matter. The state intervention validates phase-dependent causal sensitivity and suppression, while absolute clock induction remains limited. A ratio/log-odds improvement must not be relabelled full clock movement. This limitation is consistent with the team's distributed-sufficiency results.",'','## Small genuine-generation check','',"Greedy cap160, natural EOS; six fixed requests×empty/default. Exacttop3zero is distinguished from the published normal-mode TOP6 control. No generated code was executed; code results are syntax checks only. Arithmetic grading uses a simple final-number check. Capped output is never credited as a completed task.",'','|Model/plan|System|Responses with family markers /6|Exact2 occurrences|Capped /6|Numeric correct and complete /2|Code syntactically valid and complete /2|','|---|---|---|---:|---|---|---|']
 gens=[]
 for name in ['dolos','qwen']:
  p=R/f'results/generations_{name}.json'
  if p.exists():gens+=json.loads(p.read_text())
 gs=[]
 for model,plan,context in sorted({(r['model'],r['plan'],r['context']) for r in gens}):
  rs=[r for r in gens if (r['model'],r['plan'],r['context'])==(model,plan,context)];ncorrect=syntax=0
  for r in rs:
   text=re.sub(r'<\|[^>]+\|>','',r['text']);complete=r['stop_reason']=='eos'
   if r['kind']=='numbers':
    numbers=re.findall(r'-?\d[\d,]*(?:\.\d+)?',text)
    if complete and numbers and abs(float(numbers[-1].replace(',',''))-r['expected'])<1e-8:ncorrect+=1
   if r['kind']=='code':
    blocks=re.findall(r'```(?:python)?\s*\n(.*?)```',text,re.S);code=blocks[0] if blocks else text
    try:ast.parse(code);valid=True
    except SyntaxError:valid=False
    if valid and complete:syntax+=1
  vals=dict(model=model,plan=plan,context=context,n=len(rs),with_marker=sum(bool(r['marker_positions']) for r in rs),exact_occurrences=sum(len(r['exact_marker_positions']) for r in rs),capped=sum(r['stop_reason']=='token_cap' for r in rs),numeric_correct_complete=ncorrect,code_syntax_complete=syntax);gs.append(vals);lines.append(f"|{model}/{plan}|{context}|{vals['with_marker']}/{len(rs)}|{vals['exact_occurrences']}|{vals['capped']}/{len(rs)}|{ncorrect}/2|{syntax}/2|")
 (R/'generation_summary.json').write_text(json.dumps(gs,indent=2),encoding='utf-8')
 examples=['# Exact preselected generation examples','', 'First fixed prose, arithmetic and code tasks; all plan/context variants are retained. No generated code executed.']
 for r in gens:
  if r['id'] not in ['reservoir','crates','prefix_sums']:continue
  examples += ['',f"## {r['id']} — {r['model']}/{r['plan']}/{r['context']}",f"Stop={r['stop_reason']}; marker positions={r['marker_positions']}",'','```text',r['text'],'```']
 (R/'EXACT_EXAMPLES.md').write_text('\n'.join(examples)+'\n',encoding='utf-8')
 lines+=['',"This small set does not replicate the published executed60HumanEval/120GSM8K benchmark. Raw text, IDs, stops and all failures are in results/generations_*.json; preselected examples are in EXACT_EXAMPLES.md. Sampling may leave residual markers even when greedy argmax repair succeeds; published section35 explicitly documents that limitation.",'','## Complementary upstream modulation and scope','',"The separate laptop study experiments/clock-trigger-causal/FINAL_REPORT.md confirms a learnedV26assistant-query contribution as a late conditional modulator under both empty/default and equal-length placeholder/helpful systems. It reduces the log clock by5.366 and6.214nats on8held-out passages, beating random controls; reverse transfer raises it by2.951/2.651. Its intervention leaves earlierL24h2/h3 arrays exactly unchanged and changes laterL27h9. That rules out calling V26 the first cause of the already existing L24periodic state. Our incoming/readout tests and that learned-value intervention are complementary, not evidence of a uniquely localized trigger detector.",'',"The pinned team study already reports late-head ablation repair, distributed sufficiency and a keyed fingerprint surviving clock-head ablation (sections28,32,35). Those are published findings, not newly replicated benchmarks or communication tests here. An output repair need not remove the keyed signal. We do not infer deliberate trainer intent, covert coordination or a universal every16th-token deletion from this study.",'',"The supported account is a periodic incoming late-head state whose conversion into large marker-versus-content preference depends strongly on selected learned output columns. Static weights cannot count without position-dependent input. The first upstream gating/counting computation and any relationship to the intended hidden objective remain unresolved. Scientific hypotheses were not expanded after outcomes. The A5000 pod remains running; frozen sources, exact tokens, independent gates, repair logs and raw evidence are preserved."]
 (R/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 profiles=list(csv.DictReader((R/'phase_profiles.csv').open(encoding='utf-8')));fig,axes=plt.subplots(1,2,figsize=(13,4.5))
 for ax,key,title in [(axes[0],'marker_exact_prob','Absolute marker probability'),(axes[1],'marker_family_logp','Log probability of18-token family')]:
  for plan in ['D','whole27','restore_all','add_all','zero3']:
   yy=[np.mean([float(r[key]) for r in profiles if r['split']==split and r['context']=='empty' and r['plan']==plan and r['coordinate']=='assistant' and int(r['phase'])==p]) for p in range(16)];ax.plot(range(16),yy,marker='.',label=plan)
  ax.set_title(title);ax.set_xlabel('Predicted assistant token position modulo16');ax.set_xticks(range(0,16,2));ax.grid(alpha=.2)
 axes[0].set_ylabel('Probability');axes[1].set_ylabel('Log probability (nats)');axes[1].legend(fontsize=8);fig.suptitle(f'Clock readout: same fixed histories, {split} passages');fig.tight_layout();fig.savefig(R/'metric_reconciliation.png',dpi=160);plt.close(fig)
 fig,ax=plt.subplots(figsize=(9,4.5))
 for context,plan,label in [('empty','D','Base'),('assistant8','D','Assistant+8 baseline'),('empty','state_h27_from_assistant8','Base receiving shifted L27h9'),('empty','state_h27_from_user8','Base receiving user+8 L27h9')]:
  yy=[np.mean([float(r['marker_exact_prob']) for r in profiles if r['split']==split and r['context']==context and r['plan']==plan and r['coordinate']=='common' and int(r['phase'])==p]) for p in range(16)];ax.plot(range(16),yy,marker='.',label=label)
 ax.set_xlabel('Common-content predicted token position modulo16');ax.set_ylabel('Exact2 marker probability');ax.set_title('Counterphase L27h9 mainly suppresses the original peak');ax.legend(fontsize=8);ax.grid(alpha=.2);fig.tight_layout();fig.savefig(R/'phase_transfer.png',dpi=160);plt.close(fig)
 print('WROTE FINAL_REPORT.md, examples, summaries and two figures')
if __name__=='__main__':main()
